const semantic = (text: string, proposal: ProposedAction, expected: Partial<ConversationTurn> = {}): ConversationTurn => ({ text, proposal, ...expected });
const set = (text: string, loadValue: number, reps: number): ConversationTurn => semantic(text, { type: "LOG_SET", set: { loadValue, reps } });
