const current = (text: string) => read(text, { type: "QUERY_CURRENT_STATE" });
const correct = (text: string, reps: number) => semantic(text, { type: "CORRECT_SET", replacement: { reps } });
const greeting = (text: string) => read(text, { type: "GREETING" });
